"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["98844"],{15627(e){e.exports=JSON.parse('{"id":"FIN-1490","slug":"mean-absolute-percentage-error","term":"Mean Absolute Percentage Error (MAPE)","also_known_as":["MAPE"],"difficulty":"Advanced","definition":"Mean absolute percentage error (MAPE) is a measure of forecast accuracy, calculated as the average of the absolute forecast errors expressed as percentages of the actual values.","explanation":["MAPE shows, on average, how far forecasts are from actual results in percentage terms, making it easy to understand and to compare across series of different sizes.","For example, suppose actual sales in three months were 100, 200 and 400, and the forecasts were 110, 180 and 420. The absolute percentage errors are 10%, 10% and 5%. The MAPE is the average, about 8.3%.","MAPE is popular in business forecasting because percentages are intuitive. A MAPE of 5% suggests forecasts are typically within about 5% of actual results.","It has limitations. It cannot be calculated when actual values are zero, and it becomes very large and unstable when actual values are close to zero. It also treats over-forecasts and under-forecasts asymmetrically in some situations. Alternatives, such as weighted versions of MAPE or scaled error measures, are sometimes used instead."],"note":"","total":1500,"prev":{"slug":"maximum-drawdown","term":"Maximum Drawdown"},"next":{"slug":"median","term":"Median"}}')}}]);